package com.coderaccotax.javatutorial.generics;

import java.util.ArrayList;
import java.util.List;

public class AutomaticBytecodeCastingDemo {

    public static void main(String[] args) {
        System.out.println("==========================================================================");
        System.out.println(" TOPIC 2: AUTOMATIC BYTECODE CAST INSERTION - BARRACKPORE");
        System.out.println("==========================================================================\n");

        List<String> list = new ArrayList<>();
        list.add("Swadeep Paul (Barrackpore)");

        // Developer writes clean code without manual casting:
        String name = list.get(0);

        System.out.println(">>> 1. Retrieved String element: " + name);

        System.out.println("\n>>> WHAT THE COMPILER ACTUALLY GENERATES BEHIND THE SCENES:");
        System.out.println("  1. In pre-Java 5, developers wrote: 'String name = (String) list.get(0);'");
        System.out.println("  2. In modern Java, developers write: 'String name = list.get(0);'");
        System.out.println("  3. IN BYTECODE: The javac compiler automatically generates the 'checkcast java/lang/String' instruction!");
        System.out.println("  4. You write clean code; the compiler inserts guaranteed safe bytecode casts automatically.");

        System.out.println("\n==========================================================================");
    }
}